public class VisibilityExample {
    private int normalVar = 0;
    private volatile boolean flag = false;

    public void writer() {
        normalVar = 42; // Happens-before flag = true
        flag = true;    // Volatile write
    }

    public void reader() {
        if (flag) {     // Volatile read
            // Guaranteed to see normalVar == 42
            System.out.println(normalVar);
        }
    }
}
